"use client";

import * as React from "react";
import styles from "../styles/pinned-steps.module.css";

interface SmoothScrollState {
  /** Current scrollTop of the viewport in px */
  scroll: number;
  /** Maximum scrollTop in px */
  limit: number;
  /** scroll / limit, 0..1 */
  progress: number;
}

interface SmoothScrollOptions {
  lerp: number;
  wheelMultiplier: number;
  smooth: boolean;
  onScroll?: (state: SmoothScrollState) => void;
}

const clamp = (v: number, min: number, max: number) => Math.min(max, Math.max(min, v));

function usePrefersReducedMotion(): boolean {
  const [reduced, setReduced] = React.useState(false);
  React.useEffect(() => {
    const mq = window.matchMedia("(prefers-reduced-motion: reduce)");
    const update = () => setReduced(mq.matches);
    update();
    mq.addEventListener("change", update);
    return () => mq.removeEventListener("change", update);
  }, []);
  return reduced;
}

/** True when a nested scrollable element under the pointer can still scroll in the wheel direction. */
function nestedCanScroll(node: EventTarget | null, root: HTMLElement, dy: number): boolean {
  let el: Element | null = node instanceof Element ? node : null;
  while (el && el !== root) {
    if (el instanceof HTMLElement) {
      if (el.dataset.mfScrollPrevent !== undefined) return true;
      const oy = window.getComputedStyle(el).overflowY;
      if ((oy === "auto" || oy === "scroll") && el.scrollHeight > el.clientHeight + 1) {
        if (dy < 0 ? el.scrollTop > 0 : el.scrollTop + el.clientHeight < el.scrollHeight - 1) return true;
      }
    }
    el = el.parentElement;
  }
  return false;
}

/**
 * Self-contained smooth scroller for an overflow container: wheel input sets a target, a rAF
 * loop eases scrollTop toward it (frame-rate independent) and stops when settled. Touch,
 * keyboard and scrollbar stay native; at the edges wheel events are released to the page.
 */
function useSmoothScroll(
  containerRef: React.RefObject<HTMLElement | null>,
  { lerp, wheelMultiplier, smooth, onScroll }: SmoothScrollOptions,
) {
  const callbackRef = React.useRef(onScroll);
  React.useEffect(() => {
    callbackRef.current = onScroll;
  }, [onScroll]);

  React.useEffect(() => {
    const el = containerRef.current;
    if (!el) return;
    const ease = clamp(Number.isFinite(lerp) ? lerp : 0.1, 0.01, 1);
    const multiplier = Number.isFinite(wheelMultiplier) ? wheelMultiplier : 1;
    let target = el.scrollTop;
    let current = target;
    let raf = 0;
    let lastTime = 0;
    const getLimit = () => Math.max(0, el.scrollHeight - el.clientHeight);
    const emit = () => {
      const limit = getLimit();
      const scroll = clamp(el.scrollTop, 0, limit);
      callbackRef.current?.({ scroll, limit, progress: limit > 0 ? scroll / limit : 0 });
    };
    const stop = () => {
      raf = 0;
      lastTime = 0;
    };
    const tick = (time: number) => {
      const frames = (lastTime ? clamp(time - lastTime, 1, 64) : 16.667) / 16.667;
      lastTime = time;
      target = clamp(target, 0, getLimit());
      if (Math.abs(el.scrollTop - current) > 2) {
        // Scrollbar drag, keyboard or touch moved the viewport: hand control back.
        current = target = el.scrollTop;
        stop();
        emit();
        return;
      }
      current += (target - current) * (1 - Math.pow(1 - ease, frames));
      if (Math.abs(target - current) < 0.35) current = target;
      el.scrollTop = current;
      emit();
      if (current === target) stop();
      else raf = requestAnimationFrame(tick);
    };
    const onWheel = (event: WheelEvent) => {
      if (event.ctrlKey || event.defaultPrevented || Math.abs(event.deltaX) > Math.abs(event.deltaY)) return;
      let dy = event.deltaY;
      if (event.deltaMode === 1) dy *= 16;
      else if (event.deltaMode === 2) dy *= el.clientHeight;
      dy *= multiplier;
      if (dy === 0 || nestedCanScroll(event.target, el, dy)) return;
      const limit = getLimit();
      if (!raf) current = target = el.scrollTop;
      // Release to native scrolling at the edges so the page is never trapped.
      if ((dy < 0 && target <= 0) || (dy > 0 && target >= limit - 0.5)) return;
      event.preventDefault();
      target = clamp(target + dy, 0, limit);
      if (!raf) raf = requestAnimationFrame(tick);
    };
    const onNativeScroll = () => {
      if (raf) return;
      current = target = el.scrollTop;
      emit();
    };
    if (smooth) el.addEventListener("wheel", onWheel, { passive: false });
    el.addEventListener("scroll", onNativeScroll, { passive: true });
    const ro = new ResizeObserver(emit);
    ro.observe(el);
    if (el.firstElementChild) ro.observe(el.firstElementChild);
    emit();
    return () => {
      if (smooth) el.removeEventListener("wheel", onWheel);
      el.removeEventListener("scroll", onNativeScroll);
      ro.disconnect();
      if (raf) cancelAnimationFrame(raf);
    };
  }, [containerRef, lerp, wheelMultiplier, smooth]);
}

export interface PinnedStepsProps {
  /** Step titles, one pinned step per item */
  steps?: string[];
  /** Heading shown above the step list (also the region label) */
  title?: string;
  /** Accent color for the active step, progress and visuals */
  accentColor?: string;
  /** How the right-hand visual changes between steps */
  transition?: "fade" | "slide" | "zoom";
  /** Duration in ms of the visual crossfade */
  transitionDuration?: number;
  /** Show the progress line inside the active step and the overall bar */
  showProgress?: boolean;
  /** Viewport height in px */
  height?: number;
  /** Viewport corner radius in px */
  borderRadius?: number;
  /** Interpolation factor per 60fps frame (0.05 = floaty, 0.3 = snappy) */
  lerp?: number;
  /** Multiplier applied to wheel / trackpad deltas */
  wheelMultiplier?: number;
  /** Enable smooth wheel scrolling (native scrolling when false or under reduced motion) */
  smooth?: boolean;
  /** Optional className merged onto the root */
  className?: string;
  /** Inline styles merged onto the root */
  style?: React.CSSProperties;
}

const DEFAULT_STEPS = ["Connect your sources", "Map the signals", "Watch it trend", "Ship the insight"];
const DESCRIPTIONS = [
  "Plug in databases, events and spreadsheets in a couple of clicks. Schemas sync automatically.",
  "Group raw events into the metrics your team actually talks about, with zero SQL.",
  "Live charts update as data lands, so changes surface the minute they happen.",
  "Share a link, schedule a digest or push alerts straight to the channel that cares.",
];
const NODES: [number, number][] = [
  [40, 60],
  [100, 30],
  [160, 60],
  [100, 90],
];

function StepArt({ kind }: { kind: number }) {
  if (kind === 0) {
    return (
      <svg viewBox="0 0 200 120" className={styles.art}>
        <path d="M40 60 L100 30 L160 60 L100 90 Z M40 60 L160 60 M100 30 L100 90" className={styles.stroke} />
        {NODES.map(([x, y]) => (
          <circle key={`${x}-${y}`} cx={x} cy={y} r="11" className={styles.node} />
        ))}
        <circle cx="100" cy="60" r="16" className={styles.hub} />
      </svg>
    );
  }
  if (kind === 1) {
    return (
      <svg viewBox="0 0 200 120" className={styles.art}>
        {[48, 80, 36, 96, 64, 88, 56].map((h, b) => (
          <rect key={b} x={22 + b * 23} y={104 - h} width="15" height={h} rx="4" className={b === 3 ? styles.hub : styles.node} />
        ))}
      </svg>
    );
  }
  if (kind === 2) {
    return (
      <svg viewBox="0 0 200 120" className={styles.art}>
        <path d="M14 96 C 44 90, 54 60, 84 66 S 130 30, 186 20 L186 108 L14 108 Z" className={styles.area} />
        <path d="M14 96 C 44 90, 54 60, 84 66 S 130 30, 186 20" className={styles.stroke} />
        <circle cx="186" cy="20" r="6" className={styles.hub} />
      </svg>
    );
  }
  return (
    <svg viewBox="0 0 200 120" className={styles.art}>
      <circle cx="100" cy="60" r="40" className={styles.area} />
      <circle cx="100" cy="60" r="40" className={styles.stroke} />
      <path d="M82 61 L95 74 L120 47" className={styles.check} />
    </svg>
  );
}

export function PinnedSteps({
  steps = DEFAULT_STEPS,
  title = "How it works",
  accentColor = "#34d399",
  transition = "slide",
  transitionDuration = 450,
  showProgress = true,
  height = 380,
  borderRadius = 20,
  lerp = 0.1,
  wheelMultiplier = 1,
  smooth = true,
  className = "",
  style,
}: PinnedStepsProps) {
  const reduced = usePrefersReducedMotion();
  const viewportRef = React.useRef<HTMLDivElement>(null);
  const stageRef = React.useRef<HTMLDivElement>(null);
  const [active, setActive] = React.useState(0);
  const total = Math.max(1, steps.length);
  const perStep = Math.round(height * 0.8);

  const handleScroll = React.useCallback(
    ({ progress }: SmoothScrollState) => {
      const t = progress * total;
      const index = clamp(Math.floor(t), 0, total - 1);
      const stage = stageRef.current;
      if (stage) {
        stage.style.setProperty("--mf-pst-p", progress.toFixed(4));
        stage.style.setProperty("--mf-pst-l", clamp(t - index, 0, 1).toFixed(4));
      }
      setActive(index);
    },
    [total],
  );

  useSmoothScroll(viewportRef, { lerp, wheelMultiplier, smooth: smooth && !reduced, onScroll: handleScroll });

  const goTo = (i: number) => {
    const el = viewportRef.current;
    if (!el) return;
    const limit = el.scrollHeight - el.clientHeight;
    el.scrollTo({ top: ((i + 0.04) / total) * limit, behavior: reduced ? "auto" : "smooth" });
  };

  const vars = {
    "--mf-pst-h": `${height}px`,
    "--mf-pst-r": `${borderRadius}px`,
    "--mf-pst-accent": accentColor,
    "--mf-pst-dur": `${Math.max(0, transitionDuration)}ms`,
    ...style,
  } as React.CSSProperties;

  return (
    <div style={vars} className={`${styles.root} ${className}`.trim()} data-transition={transition}>
      <div ref={viewportRef} className={styles.viewport} tabIndex={0} role="region" aria-label={title}>
        <div style={{ height: height + total * perStep }}>
          <div ref={stageRef} className={styles.stage}>
            <div className={styles.left}>
              <span className={styles.kicker}>{`Step ${active + 1} of ${total}`}</span>
              <h3 className={styles.title}>{title}</h3>
              <ol className={styles.steps}>
                {steps.map((step, i) => (
                  <li key={`${step}-${i}`} className={styles.step} data-state={i === active ? "active" : i < active ? "done" : "todo"}>
                    <button
                      type="button"
                      className={styles.stepButton}
                      aria-current={i === active ? "step" : undefined}
                      onClick={() => goTo(i)}
                    >
                      <span className={styles.badge} aria-hidden="true">
                        {i < active ? "✓" : i + 1}
                      </span>
                      <span className={styles.stepTitle}>{step}</span>
                    </button>
                    <div className={styles.detail}>
                      <div className={styles.detailInner}>
                        {showProgress && (
                          <span className={styles.line} aria-hidden="true">
                            <span className={styles.lineFill} />
                          </span>
                        )}
                        <p className={styles.desc}>{DESCRIPTIONS[i % DESCRIPTIONS.length]}</p>
                      </div>
                    </div>
                  </li>
                ))}
              </ol>
            </div>
            <div className={styles.right} aria-hidden="true">
              <div className={styles.frame}>
                <div className={styles.chrome}>
                  <span className={styles.light} />
                  <span className={styles.light} />
                  <span className={styles.light} />
                  {showProgress && (
                    <span className={styles.bar}>
                      <span className={styles.barFill} />
                    </span>
                  )}
                </div>
                {steps.map((step, i) => (
                  <div
                    key={`${step}-v-${i}`}
                    className={styles.visual}
                    data-state={i === active ? "active" : i < active ? "before" : "after"}
                    style={{ "--mf-pst-hue": `${i * 38}deg` } as React.CSSProperties}
                  >
                    <StepArt kind={i % 4} />
                    <span className={styles.visualLabel}>{step}</span>
                  </div>
                ))}
              </div>
              <div className={styles.dots}>
                {steps.map((step, i) => (
                  <span key={`${step}-d-${i}`} className={styles.dot} data-active={i === active ? "" : undefined} />
                ))}
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

.root {
  position: relative;
  width: 100%;
  height: var(--mf-pst-h, 380px);
  border-radius: var(--mf-pst-r, 20px);
  overflow: hidden;
  border: 1px solid var(--mf-border, #2e2e38);
  background: var(--mf-surface, #141419);
  color: var(--mf-fg, #f4f4f6);
  container-type: inline-size;
  isolation: isolate;
}

.root *,
.root *::before,
.root *::after {
  box-sizing: border-box;
}

.viewport {
  position: relative;
  height: 100%;
  overflow-x: hidden;
  overflow-y: auto;
  overscroll-behavior: auto;
  scroll-behavior: auto;
  scrollbar-width: thin;
  scrollbar-color: var(--mf-border, #2e2e38) transparent;
}

.viewport:focus-visible {
  outline: 2px solid var(--mf-fg, #e4e4e7);
  outline-offset: -2px;
}

.stage {
  --mf-pst-p: 0;
  --mf-pst-l: 0;
  position: sticky;
  top: 0;
  display: grid;
  grid-template-columns: minmax(0, 0.95fr) minmax(0, 1.05fr);
  gap: clamp(1rem, 4cqi, 2.5rem);
  align-items: center;
  height: var(--mf-pst-h, 380px);
  padding: 1.25rem clamp(1rem, 5cqi, 2.75rem);
  overflow: hidden;
}

.left {
  display: flex;
  flex-direction: column;
  gap: 0.45rem;
  min-width: 0;
}

.kicker {
  font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  font-size: 0.7rem;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--mf-pst-accent, #34d399);
}

.title {
  margin: 0 0 0.35rem;
  font-size: clamp(1.3rem, 3.6cqi, 1.85rem);
  font-weight: 700;
  line-height: 1.05;
  letter-spacing: -0.035em;
}

.steps {
  display: flex;
  flex-direction: column;
  gap: 0.15rem;
  margin: 0;
  padding: 0;
  list-style: none;
}

.step {
  border-radius: 12px;
  transition: background-color 250ms ease;
}

.step[data-state="active"] {
  background: var(--mf-surface-raised, #1b1b22);
}

.stepButton {
  display: flex;
  align-items: center;
  gap: 0.65rem;
  width: 100%;
  padding: 0.45rem 0.55rem;
  border: 0;
  border-radius: 12px;
  background: none;
  color: var(--mf-muted, #a1a1aa);
  font: inherit;
  text-align: left;
  cursor: pointer;
  transition: color 250ms ease;
}

.stepButton:focus-visible {
  outline: 2px solid var(--mf-fg, #e4e4e7);
  outline-offset: 0;
}

.step[data-state="active"] .stepButton {
  color: var(--mf-fg, #f4f4f6);
}

.badge {
  display: grid;
  flex: none;
  place-items: center;
  width: 1.5rem;
  height: 1.5rem;
  border: 1px solid var(--mf-border-strong, #3f3f4a);
  border-radius: 999px;
  font-size: 0.7rem;
  font-weight: 600;
  transition: background-color 250ms ease, border-color 250ms ease, color 250ms ease;
}

.step[data-state="active"] .badge,
.step[data-state="done"] .badge {
  border-color: var(--mf-pst-accent, #34d399);
  background: var(--mf-pst-accent, #34d399);
  color: #0b0b0f;
}

.step[data-state="done"] .badge {
  background: color-mix(in srgb, var(--mf-pst-accent, #34d399) 20%, transparent);
  color: var(--mf-pst-accent, #34d399);
}

.stepTitle {
  font-size: 0.92rem;
  font-weight: 600;
  letter-spacing: -0.01em;
}

.detail {
  display: grid;
  grid-template-rows: 0fr;
  transition: grid-template-rows 350ms cubic-bezier(0.22, 1, 0.36, 1);
}

.step[data-state="active"] .detail {
  grid-template-rows: 1fr;
}

.detailInner {
  position: relative;
  min-height: 0;
  overflow: hidden;
}

.line {
  position: absolute;
  top: 0.2rem;
  bottom: 0.7rem;
  left: calc(0.55rem + 0.75rem - 1px);
  width: 2px;
  border-radius: 2px;
  background: var(--mf-border, #2e2e38);
  overflow: hidden;
}

.lineFill {
  position: absolute;
  inset: 0;
  background: var(--mf-pst-accent, #34d399);
  transform: scaleY(var(--mf-pst-l));
  transform-origin: 50% 0%;
}

.desc {
  margin: 0;
  padding: 0 0.75rem 0.65rem 2.7rem;
  color: var(--mf-muted, #a1a1aa);
  font-size: 0.8rem;
  line-height: 1.5;
}

.right {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 0.75rem;
  min-width: 0;
}

.frame {
  position: relative;
  width: 100%;
  aspect-ratio: 4 / 3;
  max-height: calc(var(--mf-pst-h, 380px) - 4.5rem);
  border: 1px solid var(--mf-border, #2e2e38);
  border-radius: 16px;
  overflow: hidden;
  background: var(--mf-surface-raised, #1b1b22);
  box-shadow: 0 24px 48px -28px rgba(0, 0, 0, 0.6);
}

.chrome {
  position: absolute;
  inset: 0 0 auto;
  z-index: 2;
  display: flex;
  align-items: center;
  gap: 5px;
  height: 30px;
  padding: 0 0.7rem;
  border-bottom: 1px solid var(--mf-border, #2e2e38);
  background: var(--mf-surface-raised, #1b1b22);
}

.light {
  width: 8px;
  height: 8px;
  border-radius: 999px;
  background: var(--mf-border-strong, #3f3f4a);
}

.bar {
  position: relative;
  flex: 1;
  height: 4px;
  margin-left: 0.6rem;
  border-radius: 4px;
  background: var(--mf-border, #2e2e38);
  overflow: hidden;
}

.barFill {
  position: absolute;
  inset: 0;
  background: var(--mf-pst-accent, #34d399);
  transform: scaleX(var(--mf-pst-p));
  transform-origin: 0% 50%;
}

.visual {
  position: absolute;
  inset: 30px 0 0;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 0.4rem;
  padding: 0.9rem;
  isolation: isolate;
  opacity: 0;
  transition:
    opacity var(--mf-pst-dur, 450ms) ease,
    transform var(--mf-pst-dur, 450ms) cubic-bezier(0.22, 1, 0.36, 1);
}

.visual::before {
  content: "";
  position: absolute;
  inset: 0;
  z-index: -1;
  background:
    radial-gradient(80% 90% at 20% 10%, color-mix(in srgb, var(--mf-pst-accent, #34d399) 38%, transparent), transparent 70%),
    radial-gradient(70% 80% at 90% 100%, color-mix(in srgb, #818cf8 34%, transparent), transparent 70%);
  filter: hue-rotate(var(--mf-pst-hue, 0deg));
}

.visual[data-state="active"] {
  opacity: 1;
}

.root[data-transition="slide"] .visual[data-state="before"] {
  transform: translateY(-18%);
}

.root[data-transition="slide"] .visual[data-state="after"] {
  transform: translateY(18%);
}

.root[data-transition="zoom"] .visual[data-state="before"] {
  transform: scale(1.12);
}

.root[data-transition="zoom"] .visual[data-state="after"] {
  transform: scale(0.88);
}

.art {
  width: 72%;
  max-height: 72%;
  overflow: visible;
}

.stroke {
  fill: none;
  stroke: var(--mf-pst-accent, #34d399);
  stroke-width: 3;
  stroke-linecap: round;
  stroke-linejoin: round;
}

.node {
  fill: color-mix(in srgb, var(--mf-pst-accent, #34d399) 30%, var(--mf-surface-raised, #1b1b22));
  stroke: var(--mf-pst-accent, #34d399);
  stroke-width: 2;
}

.hub {
  fill: var(--mf-pst-accent, #34d399);
}

.area {
  fill: color-mix(in srgb, var(--mf-pst-accent, #34d399) 22%, transparent);
}

.check {
  fill: none;
  stroke: var(--mf-fg, #f4f4f6);
  stroke-width: 7;
  stroke-linecap: round;
  stroke-linejoin: round;
}

.visualLabel {
  font-size: 0.78rem;
  font-weight: 600;
  color: var(--mf-fg, #f4f4f6);
}

.dots {
  display: flex;
  gap: 6px;
}

.dot {
  width: 7px;
  height: 7px;
  border-radius: 999px;
  background: var(--mf-border-strong, #3f3f4a);
  transition: width 250ms ease, background-color 250ms ease;
}

.dot[data-active] {
  width: 22px;
  background: var(--mf-pst-accent, #34d399);
}

@media (prefers-reduced-motion: reduce) {
  .visual,
  .detail,
  .step,
  .stepButton,
  .badge,
  .dot {
    transition: none;
  }

  .root .visual[data-state] {
    transform: none;
  }
}

