"use client";

import { useEffect, useRef, useState } from "react";

const steps = ["Connect your sources", "Map the signals", "Watch it trend", "Ship the insight"];
const tints = ["from-emerald-400/40", "from-sky-400/40", "from-violet-400/40", "from-amber-400/40"];

export function PinnedStepsTailwind() {
  const ref = useRef(null);
  const [active, setActive] = useState(0);
  useEffect(() => {
    const el = ref.current;
    const update = () => {
      const max = el.scrollHeight - el.clientHeight;
      const p = max > 0 ? el.scrollTop / max : 0;
      setActive(Math.min(steps.length - 1, Math.floor(p * steps.length)));
    };
    el.addEventListener("scroll", update, { passive: true });
    return () => el.removeEventListener("scroll", update);
  }, []);
  return (
    <div ref={ref} tabIndex={0} className="h-[380px] w-full overflow-y-auto rounded-[20px] border border-zinc-800 bg-zinc-900 text-zinc-100">
      <div style={{ height: 380 + steps.length * 300 }}>
        <div className="sticky top-0 grid h-[380px] grid-cols-2 items-center gap-8 px-10">
          <div>
            <p className="text-xs uppercase tracking-widest text-emerald-400">Step {active + 1} of {steps.length}</p>
            <h3 className="mb-3 text-2xl font-bold">How it works</h3>
            <ol className="space-y-1">
              {steps.map((s, i) => (
                <li key={s} className={`rounded-xl px-3 py-2 text-sm font-semibold transition ${i === active ? "bg-zinc-800 text-white" : "text-zinc-500"}`}>{i + 1}. {s}</li>
              ))}
            </ol>
          </div>
          <div className="relative aspect-[4/3] overflow-hidden rounded-2xl border border-zinc-800 bg-zinc-800">
            {steps.map((s, i) => (
              <div key={s} className={`absolute inset-0 grid place-items-center bg-gradient-to-br to-transparent text-sm font-semibold transition-all duration-500 ${tints[i]} ${i === active ? "opacity-100" : "translate-y-6 opacity-0"}`}>{s}</div>
            ))}
          </div>
        </div>
      </div>
    </div>
  );
}
